import 'package:flutter/material.dart';import 'package:sehatak/core/models/pregnancy/pregnancy_models.dart';import 'package:sehatak/core/services/pregnancy_service.dart';class PregnancyDoctorDetailScreen extends StatelessWidget{final String doctorId;const PregnancyDoctorDetailScreen({super.key,required this.doctorId});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تفاصيل الطبيب')),body:FutureBuilder<PregnancyDoctor?>(future:PregnancyService().getDoctor(doctorId),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!;return ListView(padding:const EdgeInsets.all(20),children:[Center(child:CircleAvatar(radius:50,backgroundImage:d.photoUrl.isNotEmpty?NetworkImage(d.photoUrl):null,child:d.photoUrl.isEmpty?const Icon(Icons.person,size:45):null)),const SizedBox(height:16),Text(d.name,textAlign:TextAlign.center,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w800)),Text(d.specialty,textAlign:TextAlign.center),const SizedBox(height:16),Text('التقييم ${d.rating.toStringAsFixed(1)} • ${d.reviewCount} تقييم'),Text('الخبرة: ${d.experienceYears} سنة'),Text('العنوان: ${d.address}'),Text('الهاتف: ${d.phone}'),Text(d.isVerified?'✓ طبيب موثق':'طبيب غير موثق')]);}));}}
